package com.vaultorandroid
import android.content.*
import android.net.nsd.*
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.json.*
import java.io.File
import java.util.*
import java.util.concurrent.*
@RunWith(AndroidJUnit4::class)
class UpdateDiscoveryTest {
 init{require(android.os.Build.HARDWARE=="ranchu")}
 private val i get()=InstrumentationRegistry.getInstrumentation()
 private val ctx get()=i.targetContext
 private fun fixture():Context {val root=File(ctx.cacheDir,"update-test-"+UUID.randomUUID()).apply {mkdirs()};return object:ContextWrapper(ctx){override fun getNoBackupFilesDir()=root}}
 @Test fun originalSignedApkVerifiesAndDowngradeOrTamperedBytesAreRejected(){val context=fixture();try{val updates=VaultorUpdates(context);val apk=File(ctx.applicationInfo.sourceDir);val code=ctx.packageManager.getPackageInfo(ctx.packageName,0).longVersionCode;assertEquals(code,updates.verify(apk,code-1).getLong("versionCode"));try{updates.verify(apk,code);fail("Same version must be refused")}catch(_:IllegalArgumentException){};val bad=File(context.noBackupFilesDir,"tampered.apk");apk.copyTo(bad);java.io.RandomAccessFile(bad,"rw").use {file->file.seek(2048);val old=file.read();file.seek(2048);file.write(old xor 1)};try{updates.verify(bad,code-1);fail("Tampered APK must fail cryptographic verification")}catch(_:Exception){};assertEquals(code,ctx.packageManager.getPackageInfo(ctx.packageName,0).longVersionCode)}finally{require(context.noBackupFilesDir.canonicalPath.startsWith(ctx.cacheDir.canonicalPath+"/update-test-"));context.noBackupFilesDir.deleteRecursively()}}
 @Test fun differentlySignedApkIsRejectedBeforeInstall(){val context=fixture();try{val apk=File(ctx.getExternalFilesDir(null),"r89-fixtures/wrong-signer.apk");assertTrue("Prepare the disposable wrong-signer APK vector",apk.isFile);try{VaultorUpdates(context).verify(apk,0);fail("Wrong signer must be refused")}catch(e:IllegalArgumentException){assertTrue(e.message!!.contains("signer"))}}finally{context.noBackupFilesDir.deleteRecursively()}}
 @Test fun differentlyPackagedOriginalSignerApkIsRejected(){val context=fixture();try{val apk=File(ctx.getExternalFilesDir(null),"r89-fixtures/wrong-package.apk");assertTrue(apk.isFile);try{VaultorUpdates(context).verify(apk,0);fail("Wrong package must be refused")}catch(e:IllegalArgumentException){assertTrue(e.message!!.contains("package"))}}finally{context.noBackupFilesDir.deleteRecursively()}}
 @Test fun discoveryWithoutPermissionHasManualFallback(){if(android.os.Build.VERSION.SDK_INT<37)return;assertNotEquals(android.content.pm.PackageManager.PERMISSION_GRANTED,ctx.checkSelfPermission(android.Manifest.permission.ACCESS_LOCAL_NETWORK));val discovery=VaultorDiscovery(ctx){};val state=discovery.start();assertFalse(state.getBoolean("scanning"));assertTrue(state.getString("error").contains("permission"));assertEquals(0,state.getJSONArray("items").length());discovery.stop()}
 @Test fun realNsdProducesOnlyCandidatesAndStopsCleanly(){if(android.os.Build.VERSION.SDK_INT>=37)i.uiAutomation.grantRuntimePermission(ctx.packageName,android.Manifest.permission.ACCESS_LOCAL_NETWORK);val nsd=ctx.getSystemService(NsdManager::class.java);val registered=CountDownLatch(1);val id=UUID.randomUUID().toString();val info=NsdServiceInfo().apply {serviceType="_vaultor._tcp.";serviceName="Vaultor disposable "+id.take(8);port=8443;setAttribute("hostId",id);setAttribute("protocol","1")};val listener=object:NsdManager.RegistrationListener{override fun onServiceRegistered(info:NsdServiceInfo){registered.countDown()};override fun onRegistrationFailed(info:NsdServiceInfo,code:Int){registered.countDown()};override fun onServiceUnregistered(info:NsdServiceInfo){};override fun onUnregistrationFailed(info:NsdServiceInfo,code:Int){}};val discovery=VaultorDiscovery(ctx){};try{nsd.registerService(info,NsdManager.PROTOCOL_DNS_SD,listener);assertTrue(registered.await(10,TimeUnit.SECONDS));discovery.start();var found=false;repeat(100){if(!found){val rows=discovery.snapshot().getJSONArray("items");found=(0 until rows.length()).any {val row=rows.getJSONObject(it);row.getString("hostId")==id&&row.getString("address").startsWith("https://")};if(!found)Thread.sleep(100)}};assertTrue("NSD must resolve the disposable advertisement",found);discovery.stop();assertFalse(discovery.snapshot().getBoolean("scanning"));assertTrue(VaultorDiscovery.privateAddress("192.168.1.2"));assertFalse(VaultorDiscovery.privateAddress("203.0.113.5"));assertFalse(VaultorDiscovery.privateAddress("192.168.1.999"))}finally{discovery.stop();try{nsd.unregisterService(listener)}catch(_:Exception){}}}
 @Test fun feedSelectionNeverTreatsMetadataAsVerifiedAndSkipsWrongPackageOrProtocol(){val context=fixture();try{val code=ctx.packageManager.getPackageInfo(ctx.packageName,0).longVersionCode;val versions=mapOf("a" to (code+1),"b" to (code+2),"wrong" to (code+9),"protocol" to (code+10));val releases=JSONArray(versions.keys.map {key->JSONObject().put("tag_name","android/vtest-"+key).put("draft",false).put("assets",JSONArray().put(JSONObject().put("name","android-release.json").put("browser_download_url","https://github.com/meta/"+key)).put(JSONObject().put("name","Vaultor-"+key+".apk").put("size",100).put("browser_download_url","https://github.com/apk/"+key)))})
 val updates=VaultorUpdates(context,metadataFetcher={url->if(url.contains("per_page"))releases.toString()else {val key=url.substringAfterLast('/');JSONObject().put("applicationId",if(key=="wrong")"wrong.package"else "com.vaultor.app").put("versionCode",versions.getValue(key)).put("versionName",key).put("minimumApi",36).put("apiProtocol",if(key=="protocol")4 else 3).put("size",100).put("sha256","0".repeat(64)).put("apk","Vaultor-"+key+".apk").toString()}});updates.check();var state=updates.snapshot();repeat(200){if(state.optString("phase") !in listOf("available","error")){Thread.sleep(20);state=updates.snapshot()}};assertEquals(state.optString("detail"),"available",state.getString("phase"));assertEquals(code+2,state.getJSONObject("available").getLong("versionCode"));assertFalse(state.has("candidate"));assertEquals(code,ctx.packageManager.getPackageInfo(ctx.packageName,0).longVersionCode)
 }finally{context.noBackupFilesDir.deleteRecursively()}}

 @Test fun interruptedPrivateApkStagingIsNeverAnInstallableCandidate(){val context=fixture();try{val updates=VaultorUpdates(context);val method=VaultorUpdates::class.java.getDeclaredMethod("stage",java.io.InputStream::class.java,JSONObject::class.java).apply{isAccessible=true};var produced=0;val broken=object:java.io.InputStream(){override fun read():Int=error("Use buffered reads");override fun read(buffer:ByteArray,offset:Int,length:Int):Int{if(produced>=1048576)throw java.io.IOException("Disposable provider interrupted");val n=minOf(length,1048576-produced);java.util.Arrays.fill(buffer,offset,offset+n,42.toByte());produced+=n;return n}};try{method.invoke(updates,broken,null);fail("Interrupted provider must refuse staging")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is java.io.IOException)};val recovered=VaultorUpdates(context).snapshot();assertEquals("interrupted",recovered.getString("phase"));assertFalse(recovered.has("candidate"));assertTrue(java.io.File(context.noBackupFilesDir,"updates-v1/candidate.part").isFile);assertFalse(java.io.File(context.noBackupFilesDir,"updates-v1/candidate.apk").exists())}finally{context.noBackupFilesDir.deleteRecursively()}}

}
